SELECT /*+ MAX_EXECUTION_TIME(10000) */ x.op_id, x.module, x.operation_type, x.operation_time, x.src, r.row_idx, r.strategyId, r.ruleId, r.featureId, r.status_v, r.execPriority, r.conditionType, CASE WHEN r.ruleName LIKE '%countryCode%' OR r.ruleName LIKE '%区号%' OR r.ruleName LIKE '%Province%' OR r.ruleName LIKE '%次数%' THEN r.conditionValue ELSE CONCAT('len=', CHAR_LENGTH(r.conditionValue)) END AS right_value, CASE WHEN r.ruleName LIKE '%countryCode%' OR r.ruleName LIKE '%区号%' OR r.ruleName LIKE '%Province%' OR r.ruleName LIKE '%次数%' THEN r.ruleName ELSE CONCAT('len=', CHAR_LENGTH(r.ruleName)) END AS rule_name_g FROM (SELECT id AS op_id, module, operation_type, operation_time, 'before' AS src, CAST(before_data AS JSON) AS j FROM luckyus_iriskcontrolservice.t_operation_log WHERE operation_time >= '2026-10-10 00:00:00' AND operation_time < '2026-10-11 00:00:00' AND JSON_VALID(before_data) UNION ALL SELECT id, module, operation_type, operation_time, 'after', CAST(after_data AS JSON) FROM luckyus_iriskcontrolservice.t_operation_log WHERE operation_time >= '2026-10-10 00:00:00' AND operation_time < '2026-10-11 00:00:00' AND JSON_VALID(after_data)) x, JSON_TABLE(JSON_EXTRACT(x.j, '$.rows'), '$[*]' COLUMNS (row_idx FOR ORDINALITY, strategyId VARCHAR(64) PATH '$.strategyId', ruleId VARCHAR(64) PATH '$.ruleId', featureId VARCHAR(64) PATH '$.featureId', status_v VARCHAR(16) PATH '$.status', execPriority VARCHAR(32) PATH '$.execPriority', conditionType VARCHAR(64) PATH '$.conditionType', conditionValue VARCHAR(4000) PATH '$.conditionValue', ruleName VARCHAR(512) PATH '$.ruleName')) r WHERE r.strategyId LIKE 'strategy_eoHQ6Qs_FRqp' OR r.ruleId IN (SELECT rule_id FROM luckyus_iriskcontrolservice.t_rms_engine_strategy_relation WHERE strategy_id LIKE 'strategy_eoHQ6Qs_FRqp') OR r.featureId IN (SELECT ru.feature_id FROM luckyus_iriskcontrolservice.t_rms_engine_rule ru JOIN luckyus_iriskcontrolservice.t_rms_engine_strategy_relation re ON re.rule_id = ru.rule_id WHERE re.strategy_id LIKE 'strategy_eoHQ6Qs_FRqp')
